def verify(witness):
    k_min = witness["k_min"]
    k_max = witness["k_max"]
    n_max = witness["n_max"]
    if k_min < 2 or k_max < k_min or n_max < 2 * k_max:
        return False

    def comb(n, r):
        if r < 0 or r > n:
            return 0
        r = min(r, n - r)
        c = 1
        for i in range(1, r + 1):
            c = c * (n - r + i) // i
        return c

    def largest_prime_factor(v):
        if v < 2:
            return 1
        largest = 1
        d = 2
        while d * d <= v:
            while v % d == 0:
                if d > largest:
                    largest = d
                v = v // d
            d = d + 1
        if v > 1 and v > largest:
            largest = v
        return largest

    checked = 0
    for k in range(k_min, k_max + 1):
        for n in range(2 * k, n_max + 1):
            c = comb(n, k)
            if c < 2:
                return False
            if largest_prime_factor(c) <= k:
                return False
            checked = checked + 1
    return checked > 0

result = verify({"k_min": 2, "k_max": 40, "n_max": 400})
assert result == True
